// Design: docs/architecture/testing/test-health.md -- the committed artifacts
//
// pyjson.go writes the bytes `json.dumps` writes, and nothing else.
//
// It exists because two of this tool's three artifacts are COMMITTED and
// byte-compared: test/health/latest.json is regenerated by one half and read
// by the other, and test/health/history.ndjson is appended to. While the
// script and the command both run, a difference of one character in a number
// or one key out of order is a diff in a committed file, and the staleness
// gate reddens for every session until somebody regenerates.
//
// Go's encoding/json is close and not equal. Three differences are
// load-bearing:
//
//   - A float that happens to be integral encodes as `100` in Go and `100.0`
//     in Python, because Python writes `repr(float)` and repr never loses the
//     point.
//   - Python escapes every non-ASCII rune as `\uXXXX` (ensure_ascii) and
//     leaves `<`, `>` and `&` alone. Go does the opposite on both counts.
//   - `sort_keys=True` orders by code point, which is what a Go map marshal
//     does -- but the PAGE renders the same data in INSERTION order, so the
//     values here carry both orders rather than one.
package testhealth

import (
	"errors"
	"sort"
	"strconv"
	"strings"

	"github.com/ze-software/ze/internal/core/textbuf"
)

// object is a JSON object that remembers the order its keys were set in.
//
// Two orders are needed at once. The page's supporting tables take their
// columns from the order the script wrote each row's keys, and the JSON sorts
// every key by code point. One structure carrying both is what keeps the two
// renderings from disagreeing about the same data.
type object struct {
	keys []string
	vals map[string]any
}

// set stores one key, appending it to the order the first time it is seen.
func (o *object) set(key string, value any) {
	if o.vals == nil {
		o.vals = make(map[string]any)
	}
	if _, seen := o.vals[key]; !seen {
		o.keys = append(o.keys, key)
	}
	o.vals[key] = value
}

// get answers a key's value, or nil when the object does not carry it. It
// cannot tell a missing key from a stored null, which is what `has` is for.
func (o object) get(key string) any { return o.vals[key] }

// has reports whether the key was set, whatever its value.
func (o object) has(key string) bool {
	_, ok := o.vals[key]
	return ok
}

// pyNum is a number read out of a JSON document, keeping the int-versus-float
// distinction Python keeps.
//
// It matters twice. `str(1)` is "1" and `str(1.0)` is "1.0", and both reach the
// page through the trend table; and a re-encoded history row must come back
// out of the file the way it went in.
type pyNum struct {
	isInt bool
	i     int64
	f     float64
}

// Float answers the number's value, which is what every comparison uses.
func (n pyNum) Float() float64 {
	if n.isInt {
		return float64(n.i)
	}
	return n.f
}

// String renders the number the way Python's `str` renders it.
func (n pyNum) String() string {
	if n.isInt {
		return textbuf.StringInt(n.i)
	}
	return pyFloatRepr(n.f)
}

// roundTo1 answers what Python's `round(value, 1)` answers.
//
// It goes through the decimal spelling rather than through `value*10`: both
// Go's formatter and Python's round are correctly rounded over the double's
// exact value and both break a tie to even, while scaling by ten introduces a
// second rounding that does neither.
func roundTo1(value float64) float64 {
	rounded, err := strconv.ParseFloat(strconv.FormatFloat(value, 'f', 1, 64), 64)
	if err != nil {
		return value
	}
	return rounded
}

// maxFloat is the largest finite double, used to name an infinity without
// importing math for one comparison.
const maxFloat = 1.7976931348623157e308

// pyFloatRepr answers what Python's `repr` answers for a float.
//
// The shortest round-tripping digits are the same in both languages. What
// differs is the presentation: Python switches to an exponent when the decimal
// point would sit at or left of the fourth place before the digits, or past
// the sixteenth after them, and it never leaves a float looking like an
// integer.
func pyFloatRepr(value float64) string {
	switch {
	case value != value:
		return "NaN"
	case value > maxFloat:
		return "Infinity"
	case value < -maxFloat:
		return "-Infinity"
	}

	fixed := strconv.FormatFloat(value, 'f', -1, 64)
	digits, exponent := shortestDigits(value)
	point := exponent + 1
	if point <= -4 || point > 16 {
		return pyExponentForm(digits, point, strings.HasPrefix(fixed, "-"))
	}

	if strings.Contains(fixed, ".") {
		return fixed
	}
	var tb textbuf.Buffer
	return tb.Str(fixed).Str(".0").String()
}

// shortestDigits answers the shortest round-tripping digit string of a float
// and the power of ten the first digit stands for.
func shortestDigits(value float64) (string, int) {
	form := strconv.FormatFloat(value, 'e', -1, 64)
	mantissa, exponent, found := strings.Cut(form, "e")
	if !found {
		return strings.TrimPrefix(form, "-"), 0
	}
	power, err := strconv.Atoi(exponent)
	if err != nil {
		power = 0
	}
	mantissa = strings.TrimPrefix(mantissa, "-")
	return strings.Replace(mantissa, ".", "", 1), power
}

// pyExponentForm renders the exponent spelling Python uses: one digit, then
// the rest after a point when there are any, then `e` and a signed exponent of
// at least two digits.
func pyExponentForm(digits string, point int, negative bool) string {
	var tb textbuf.Buffer
	if negative {
		tb.Byte('-')
	}
	tb.Byte(digits[0])
	if len(digits) > 1 {
		tb.Byte('.').Str(digits[1:])
	}
	tb.Byte('e')
	power := point - 1
	if power < 0 {
		tb.Byte('-')
		power = -power
	} else {
		tb.Byte('+')
	}
	if power < 10 {
		tb.Byte('0')
	}
	tb.Int(int64(power))
	return tb.String()
}

// errUnwritable says a value reached the encoder that Python's json module
// would have refused too. It is a Ze defect rather than anything a file holds,
// so it is reported rather than guessed around.
var errUnwritable = errors.New("testhealth: value has no JSON spelling")

// dumpIndented answers `json.dumps(value, indent=2, sort_keys=True)`.
func dumpIndented(value any) (string, error) {
	var tb textbuf.Buffer
	if err := writeValue(&tb, value, 0, true); err != nil {
		return "", err
	}
	return tb.String(), nil
}

// dumpCompact answers `json.dumps(value, separators=(",", ":"))`, which is the
// spelling one history row is appended in. Keys keep the order they were set
// in: the row is written once and read back as a record, so its order is the
// author's rather than the sorter's.
func dumpCompact(value any) (string, error) {
	var tb textbuf.Buffer
	if err := writeValue(&tb, value, 0, false); err != nil {
		return "", err
	}
	return tb.String(), nil
}

// writeValue writes one value, indenting when asked and sorting object keys
// only then. The two spellings differ in exactly those two ways.
func writeValue(tb *textbuf.Buffer, value any, depth int, indent bool) error {
	switch typed := value.(type) {
	case nil:
		tb.Str("null")
	case bool:
		if typed {
			tb.Str("true")
		} else {
			tb.Str("false")
		}
	case string:
		writeString(tb, typed)
	case int:
		tb.Int(int64(typed))
	case int64:
		tb.Int(typed)
	case float64:
		tb.Str(pyFloatRepr(typed))
	case pyNum:
		tb.Str(typed.String())
	case object:
		return writeObject(tb, typed, depth, indent)
	case []any:
		return writeArray(tb, typed, depth, indent)
	default:
		return errUnwritable
	}
	return nil
}

// writeObject writes `{...}`, empty as `{}` on one line the way Python does.
func writeObject(tb *textbuf.Buffer, value object, depth int, indent bool) error {
	if len(value.keys) == 0 {
		tb.Str("{}")
		return nil
	}
	keys := make([]string, len(value.keys))
	copy(keys, value.keys)
	if indent {
		sort.Strings(keys)
	}

	tb.Byte('{')
	for position, key := range keys {
		if position > 0 {
			tb.Byte(',')
		}
		writeGap(tb, depth+1, indent)
		writeString(tb, key)
		tb.Byte(':')
		if indent {
			tb.Byte(' ')
		}
		if err := writeValue(tb, value.vals[key], depth+1, indent); err != nil {
			return err
		}
	}
	writeGap(tb, depth, indent)
	tb.Byte('}')
	return nil
}

// writeArray writes `[...]`, empty as `[]`.
func writeArray(tb *textbuf.Buffer, value []any, depth int, indent bool) error {
	if len(value) == 0 {
		tb.Str("[]")
		return nil
	}
	tb.Byte('[')
	for position, item := range value {
		if position > 0 {
			tb.Byte(',')
		}
		writeGap(tb, depth+1, indent)
		if err := writeValue(tb, item, depth+1, indent); err != nil {
			return err
		}
	}
	writeGap(tb, depth, indent)
	tb.Byte(']')
	return nil
}

// writeGap writes the newline and the two-space indent an indented document
// carries, and nothing at all in the compact spelling.
func writeGap(tb *textbuf.Buffer, depth int, indent bool) {
	if !indent {
		return
	}
	tb.Byte('\n')
	tb.Repeat("  ", depth)
}

// writeString writes one string the way `ensure_ascii=True` writes it: the
// seven short escapes, `\u00XX` for every other control character, the rune
// escaped for anything past the last printable ASCII character, and `<`, `>`
// and `&` left exactly as they are.
func writeString(tb *textbuf.Buffer, value string) {
	tb.Byte('"')
	for _, char := range value {
		switch char {
		case '"':
			tb.Str("\\\"")
		case '\\':
			tb.Str("\\\\")
		case '\b':
			tb.Str("\\b")
		case '\f':
			tb.Str("\\f")
		case '\n':
			tb.Str("\\n")
		case '\r':
			tb.Str("\\r")
		case '\t':
			tb.Str("\\t")
		default:
			if char < 0x20 || char > 0x7e {
				writeRuneEscape(tb, char)
				continue
			}
			tb.Byte(byte(char))
		}
	}
	tb.Byte('"')
}

// writeRuneEscape writes `\uXXXX`, splitting a rune past the basic plane into
// the surrogate pair Python writes.
func writeRuneEscape(tb *textbuf.Buffer, char rune) {
	if char > 0xffff {
		offset := char - 0x10000
		writeUnit(tb, 0xd800+(offset>>10))
		writeUnit(tb, 0xdc00+(offset&0x3ff))
		return
	}
	writeUnit(tb, char)
}

// hexDigits is the alphabet Python's encoder writes an escape in, lower case.
const hexDigits = "0123456789abcdef"

// writeUnit writes one `\uXXXX` escape.
func writeUnit(tb *textbuf.Buffer, unit rune) {
	tb.Str("\\u")
	for shift := 12; shift >= 0; shift -= 4 {
		tb.Byte(hexDigits[(unit>>uint(shift))&0xf])
	}
}
